// Shared by every policy page (Privacy Policy, Terms of Service): the logo
// (light/dark aware, same images as the CRM itself) and the theme toggle.
// Uses the SAME localStorage key as the main app ('albabusinessdesk_theme',
// falling back to the pre-rename 'flowline_theme'), so a
// theme choice made in the CRM or on a policy page carries over to the other.

const POLICY_LOGO_BLACK = 'data:image/png;base64,';
const POLICY_LOGO_WHITE = 'data:image/png;base64,';

function policySetTheme(theme){
  document.documentElement.setAttribute('data-theme', theme);
  try{ localStorage.setItem('albabusinessdesk_theme', theme); }catch(e){}
  document.querySelectorAll('.policy-theme-btn').forEach(btn=>{
    btn.classList.toggle('active', btn.dataset.themeChoice===theme);
  });
  const logo = document.getElementById('policyLogo');
  if(logo) logo.src = theme==='dark' ? POLICY_LOGO_WHITE : POLICY_LOGO_BLACK;
}

document.addEventListener('DOMContentLoaded', ()=>{
  policySetTheme(document.documentElement.getAttribute('data-theme') || 'light');
  document.querySelectorAll('.policy-theme-btn').forEach(btn=>{
    btn.addEventListener('click', ()=>policySetTheme(btn.dataset.themeChoice));
  });
});
